// PARSE OLLAMA JSON & RECOVER CONTEXT
const items = $input.all();

// 1. Get the AI Response (from previous node)
const aiOutput = items[0].json;
const aiText = aiOutput.text || aiOutput.output || "";

// 2. RECOVER CONTEXT
// We grab the original context from Security & Data Prep.
const originalContext = $('Security & Data Prep').first().json;

// 3. Clean and Parse JSON
const cleanJson = aiText.replace(/```json/g, '').replace(/```/g, '').trim();

let routeData = { intent: 'agent', entity: null };
try {
  routeData = JSON.parse(cleanJson);
} catch (e) {
  // If parsing fails, default to agent
  routeData = { intent: 'agent' };
}

// 4. Allow forcedIntent from the extension to override router decision
let route = routeData.intent || 'agent';
if (originalContext.forcedIntent) {
  route = originalContext.forcedIntent;
}

// 5. Merge Everything
return [{
  json: {
    ...originalContext, // restores sessionId, userEmail, query, templateContext, etc.
    route,
    targetTicket: routeData.entity
  }
}];

// UNIVERSAL FIX FOR n8n v1.121.3
// Use $input.all() so this works regardless of how n8n groups data.
const items = $input.all();

// Safety check: Did we get data?
if (items.length === 0) {
  return [{ json: { error: "No data received" } }];
}

const firstItem = items[0].json;

// 1. SECURITY CHECK
const clientSecret = firstItem.headers ? firstItem.headers['x-extension-secret'] : '';
// NOTE: In this environment, Code nodes cannot read $env, so we keep a static secret here.
// Make sure this matches the value your extension sends in the x-extension-secret header.
const mySecret = 'my-super-secret-password-123'; // <--- CHANGE THIS TO YOUR REAL SHARED SECRET

if (clientSecret !== mySecret) {
  // Use return instead of throw to avoid crashing the workflow
  return [{ json: { error: "Unauthorized", authorized: false } }];
}

// 2. DATA NORMALIZATION
const payload = firstItem.body || firstItem;
const userEmail = payload.userLoginId || "unknown_user";

// 3. Template context (from the extension)
const templateContext = payload.templateContext || null;
const requiresFollowUp = templateContext?.requiresFollowUp || false;
const templateAction = templateContext?.templateAction || null;

// Optional: forced intent for bypassing or overriding the router decision
const forcedIntent = payload.forcedIntent || null;

// 4. Extract Ivanti configuration (for dynamic URLs and auth)
const ivantiConfig = payload.ivantiConfig || {
  baseUrl: "https://success.serviceitplus.com", // Fallback default
  apiPathPrefix: "/HEAT/api", // Fallback default
  apiKey: "" // Fallback default
};

// 5. Extract cookies for Ivanti API authentication (REQUIRED for Ivanti APIs)
const cookies = payload.cookies || "";

// 6. Extract conversation history (CRITICAL for context)
// Format: [{ role: 'user'|'assistant', content: '...', timestamp: ... }]
const conversationHistory = payload.conversationHistory || [];

// Convert conversation history to format expected by LangChain/Redis Memory
// Redis Chat Memory expects messages in format: [{ role: 'human'|'ai', content: '...' }]
const formattedHistory = conversationHistory.map(msg => {
  return {
    role: msg.role === 'user' ? 'human' : msg.role === 'assistant' ? 'ai' : msg.role,
    content: msg.content || '',
    timestamp: msg.timestamp || Date.now()
  };
});

// Return a clean object with sessionId explicitly defined
return [{
  json: {
    sessionId: userEmail, // Memory node needs this specific key
    query: payload.message || "",
    userEmail: userEmail,
    userContext: {
      ticketId: payload.ticketId || null,
      url: payload.url || ""
    },
    templateContext,
    requiresFollowUp,
    templateAction,
    forcedIntent,
    ivantiConfig: ivantiConfig, // Critical for all downstream nodes
    cookies: cookies, // Session cookies for Ivanti API authentication
    conversationHistory: formattedHistory, // Formatted conversation history for Redis Memory
    rawConversationHistory: conversationHistory // Keep original format for reference
  }
}];

// Format discovery data for the Smart Agent
let categoriesData, prioritiesData, offeringsData;

try {
  categoriesData = $('Discover Categories').first().json;
} catch (e) {
  console.log('Categories discovery failed:', e);
  categoriesData = { value: [] };
}

try {
  prioritiesData = $('Discover Priorities').first().json;
} catch (e) {
  console.log('Priorities discovery failed:', e);
  prioritiesData = { value: [] };
}

try {
  offeringsData = $('Discover Service Request Offerings').first().json;
} catch (e) {
  console.log('Offerings discovery failed:', e);
  offeringsData = { value: [] };
}

const categories = categoriesData.value || [];
const priorities = prioritiesData.value || [];
const offerings = offeringsData.value || [];

const formattedData = {
  categories: categories.map(cat => ({
    id: cat.RecId,
    name: cat.Name,
    description: cat.Description || ''
  })),
  priorities: priorities.map(pri => ({
    id: pri.RecId,
    name: pri.Name,
    order: pri.PriorityOrder || 0,
    description: pri.Description || ''
  })),
  serviceRequestOfferings: offerings.map(off => ({
    id: off.RecId,
    name: off.Name,
    description: off.Description || ''
  }))
};

// Merge with original data from Security & Data Prep
const originalData = $('Security & Data Prep').first().json;

return [{
  json: {
    ...originalData, // This preserves the real ivantiConfig from Security & Data Prep
    discoveryData: formattedData, // Renamed to avoid conflict with ivantiConfig
    availableCategories: formattedData.categories.length > 0
      ? formattedData.categories.map(c => c.name).join(', ')
      : 'Not available',
    availablePriorities: formattedData.priorities.length > 0
      ? formattedData.priorities.map(p => p.name).join(', ')
      : 'Not available',
    availableOfferings: formattedData.serviceRequestOfferings.length > 0
      ? formattedData.serviceRequestOfferings.map(o => o.name).join(', ')
      : 'Not available'
  }
}];

// UNIVERSAL FORMATTER (AI-First Edition) - Enhanced context recovery
const items = $input.all();
if (!items.length) return [{ json: { response: "No data." } }];

const data = items[0].json;
let output = "";

// RECOVER CONTEXT from upstream nodes if missing from Smart Agent output
let userEmail = data.userEmail;
let query = data.query;
let sessionId = data.sessionId;
let route = data.route;
let userContext = data.userContext;

// If context is missing (Smart Agent only outputs text), recover from upstream
if (!userEmail || !sessionId) {
  try {
    // Try Format Discovery Data (closest upstream node)
    const formatData = $('Format Discovery Data').first().json;
    if (!userEmail && formatData.userEmail) userEmail = formatData.userEmail;
    if (!sessionId && formatData.sessionId) sessionId = formatData.sessionId;
    if (!query && formatData.query) query = formatData.query;
    if (!route && formatData.route) route = formatData.route;
    if (!userContext && formatData.userContext) userContext = formatData.userContext;
  } catch (e) {
    try {
      // Fallback to Security & Data Prep (original source)
      const securityData = $('Security & Data Prep').first().json;
      if (!userEmail && securityData.userEmail) userEmail = securityData.userEmail;
      if (!sessionId && securityData.sessionId) sessionId = securityData.sessionId;
      if (!query && securityData.query) query = securityData.query;
      if (!route && securityData.route) route = securityData.route;
      if (!userContext && securityData.userContext) userContext = securityData.userContext;
    } catch (e2) {
      console.log('Could not recover context:', e2);
    }
  }
}

// PRESERVE CONTEXT
const preservedContext = {
  userEmail: userEmail || null,
  query: query || null,
  sessionId: sessionId || null,
  route: route || null,
  userContext: userContext || null
};

// 1. Smart Agent output (LangChain Agent format)
if (data.text) {
    output = data.text;
}
// 2. AI Summarizer or Chain LLM output
else if (data.output) {
    output = data.output;
}
// 3. Check for nested text/output in response object
else if (data.response?.text) {
    output = data.response.text;
}
else if (data.response?.output) {
    output = data.response.output;
}
// 4. Handle raw API data (tickets array)
else if (data.value && Array.isArray(data.value)) {
    if (data.value.length === 0) {
        output = "I couldn't find any matching records.";
    } else if (data.value[0].IncidentNumber) {
        // Format incidents/tickets
        output = data.value.map(t => `#${t.IncidentNumber}: ${t.Subject || 'No subject'}`).join('\n');
    } else if (data.value[0].Title) {
        // Format KB articles
        output = data.value.map(kb => `- ${kb.Title}`).join('\n');
    } else {
        output = "Found " + data.value.length + " record(s).";
    }
}
// 5. Handle string responses directly
else if (typeof data === 'string') {
    output = data;
}
// 6. Last resort: stringify (but try to extract meaningful content)
else {
    // Try to find any text-like fields
    const textFields = ['message', 'content', 'result', 'answer'];
    for (const field of textFields) {
        if (data[field] && typeof data[field] === 'string') {
            output = data[field];
            break;
        }
    }

    // If still no output, stringify but clean it up
    if (!output) {
        output = JSON.stringify(data, null, 2);
    }
}

// Ensure output is a string and not empty
if (!output || typeof output !== 'string') {
    output = "I received a response, but couldn't format it properly.";
}

// Return response with preserved context (both camelCase for workflow and snake_case for Supabase)
return [{
  json: {
    response: output.trim(),
    // camelCase (for workflow use)
    ...preservedContext,
    // snake_case (for Supabase nodes)
    user_email: userEmail || null,
    session_id: sessionId || null,
    message_role: 'assistant', // This is the AI response
    message_content: output.trim()
  }
}];

// Generate Contextual Suggestions based on conversation history and current context
const items = $input.all();
if (!items.length) return [{ json: { suggestions: [] } }];

const data = items[0].json;
const suggestions = [];

// Get conversation history from Security & Data Prep
let conversationHistory = [];
try {
  const securityData = $('Security & Data Prep').first().json;
  conversationHistory = securityData.rawConversationHistory || securityData.conversationHistory || [];
} catch (e) {
  console.log('Could not get conversation history:', e);
}

// Get current query and response
const query = (data.query || '').toLowerCase().trim();
const response = (data.response || '').toLowerCase().trim();
const route = data.route || null;
const userContext = data.userContext || {};

// Analyze last few messages for context
const recentMessages = conversationHistory.slice(-5);
const lastUserMessage = recentMessages.filter(m => m.role === 'user' || m.role === 'human').pop();
const lastAssistantMessage = recentMessages.filter(m => m.role === 'assistant' || m.role === 'ai').pop();
const lastUserContent = (lastUserMessage?.content || '').toLowerCase();
const lastAssistantContent = (lastAssistantMessage?.content || '').toLowerCase();

// PATTERN 1: User searched KB or knowledge base
if (lastUserContent.includes('search') && (lastUserContent.includes('kb') || lastUserContent.includes('knowledge') || lastUserContent.includes('article'))) {
  suggestions.push({
    id: 'suggest-more-kb',
    label: 'Show more results',
    prompt: 'Show me more knowledge base articles',
    icon: '🔍',
    priority: 1
  });

  if (response.includes('no result') || response.includes('couldn\'t find') || response.includes('not found')) {
    suggestions.push({
      id: 'suggest-create-ticket-after-kb',
      label: 'Create ticket',
      prompt: 'I need to create a ticket for this issue',
      icon: '➕',
      priority: 2
    });
  } else if (!response.includes('no result') && !response.includes('couldn\'t find')) {
    suggestions.push({
      id: 'suggest-create-ticket-if-needed',
      label: 'Create ticket if this doesn\'t help',
      prompt: 'This solution doesn\'t help, I need to create a ticket',
      icon: '➕',
      priority: 3
    });
  }
}

// PATTERN 2: User viewed tickets
if (lastUserContent.includes('ticket') && (lastUserContent.includes('show') || lastUserContent.includes('list') || lastUserContent.includes('my') || lastUserContent.includes('all'))) {
  suggestions.push({
    id: 'suggest-update-ticket',
    label: 'Update a ticket',
    prompt: 'I want to update one of my tickets',
    icon: '✏️',
    priority: 1
  });

  suggestions.push({
    id: 'suggest-create-new-ticket',
    label: 'Create new ticket',
    prompt: 'I need to create a new ticket',
    icon: '➕',
    priority: 2
  });

  if (response.includes('no ticket') || response.includes('don\'t have') || response.includes('closed')) {
    suggestions.push({
      id: 'suggest-search-kb-after-no-tickets',
      label: 'Search knowledge base',
      prompt: 'Search the knowledge base for common issues',
      icon: '🔍',
      priority: 3
    });
  }
}

// PATTERN 3: User just created a ticket (mentioned in response)
if (response.includes('created') && (response.includes('ticket') || response.includes('incident'))) {
  suggestions.push({
    id: 'suggest-view-all-tickets',
    label: 'View all tickets',
    prompt: 'Show me all my open tickets',
    icon: '📋',
    priority: 1
  });

  suggestions.push({
    id: 'suggest-search-kb-while-waiting',
    label: 'Search KB while waiting',
    prompt: 'Search the knowledge base for solutions while waiting',
    icon: '🔍',
    priority: 2
  });
}

// PATTERN 4: User has a problem/issue (mentioned in query or response)
if (query.includes('problem') || query.includes('issue') || query.includes('help') || query.includes('error') || query.includes('broken')) {
  // Only add if we haven't already added KB search suggestions
  const hasKbSuggestion = suggestions.some(s => s.id.includes('kb'));
  if (!hasKbSuggestion) {
    suggestions.push({
      id: 'suggest-search-kb-for-problem',
      label: 'Search knowledge base',
      prompt: 'Search the knowledge base for solutions',
      icon: '🔍',
      priority: 1
    });
  }

  // If problem not resolved, suggest creating ticket
  if (response.includes('couldn\'t') || response.includes('unable') || response.includes('not found') || response.includes('no solution')) {
    suggestions.push({
      id: 'suggest-create-ticket-for-problem',
      label: 'Create ticket',
      prompt: 'I need to create a ticket for this problem',
      icon: '➕',
      priority: 2
    });
  }
}

// PATTERN 5: User is on a ticket page (ticketId in context)
if (userContext.ticketId) {
  suggestions.push({
    id: 'suggest-view-ticket-details',
    label: 'View ticket details',
    prompt: 'Show me details about this ticket',
    icon: '📄',
    priority: 1
  });

  suggestions.push({
    id: 'suggest-update-current-ticket',
    label: 'Update this ticket',
    prompt: 'I want to update this ticket',
    icon: '✏️',
    priority: 2
  });
}

// PATTERN 6: Route-based suggestions
if (route === 'my_tickets') {
  // User just viewed their tickets
  if (!suggestions.some(s => s.id === 'suggest-create-new-ticket')) {
    suggestions.push({
      id: 'suggest-create-new-ticket-route',
      label: 'Create new ticket',
      prompt: 'I need to create a new ticket',
      icon: '➕',
      priority: 2
    });
  }
}

// DEFAULT: If no contextual suggestions, provide general quick actions
if (suggestions.length === 0) {
  suggestions.push(
    {
      id: 'default-tickets',
      label: 'Show my tickets',
      prompt: 'Show me all my open tickets',
      icon: '📋',
      priority: 1
    },
    {
      id: 'default-kb',
      label: 'Search knowledge base',
      prompt: 'Search the knowledge base',
      icon: '🔍',
      priority: 2
    },
    {
      id: 'default-help',
      label: 'I need help',
      prompt: 'I need help with',
      icon: '❓',
      priority: 3
    }
  );
}

// Limit to 5 suggestions and sort by priority
const finalSuggestions = suggestions
  .sort((a, b) => (a.priority || 999) - (b.priority || 999))
  .slice(0, 5);

// Return data with suggestions added
return [{
  json: {
    ...data, // Preserve all original data
    suggestions: finalSuggestions
  }
}];

// Only store if issue was resolved + ensure context is present
const items = $input.all();
if (items.length === 0) return []; // Return empty array to skip Supabase insert

const data = items[0].json;
const wasResolved = data.insights?.wasResolved || false;

if (!wasResolved) {
  return []; // Return empty array to skip Supabase insert
}

// CRITICAL: Ensure userEmail exists - recover from multiple sources if needed
let userEmail = data.userEmail;
let query = data.query;
let response = data.response;

// If userEmail is missing, try to recover it
if (!userEmail) {
  try {
    // Try Format Discovery Data (closest in execution path)
    const formatData = $('Format Discovery Data').first().json;
    if (formatData.userEmail) userEmail = formatData.userEmail;
    if (formatData.query && !query) query = formatData.query;
  } catch (e) {
    try {
      // Fallback to Security & Data Prep
      const securityData = $('Security & Data Prep').first().json;
      if (securityData.userEmail) userEmail = securityData.userEmail;
      if (securityData.query && !query) query = securityData.query;
    } catch (e2) {
      console.log('Could not recover context:', e2);
    }
  }
}

// VALIDATION: If userEmail is still missing, skip storage to prevent DB error
if (!userEmail || userEmail === 'unknown_user') {
  console.warn('Check If Resolved: userEmail is missing or invalid, skipping storage');
  return []; // Return empty array to skip Supabase insert
}

// Ensure all required fields are present
if (!query) query = data.query || 'Unknown issue';
if (!response) response = data.response || 'No solution recorded';

// Final validation: Ensure all required fields are non-empty
if (!userEmail || !query || !response) {
  console.warn('Check If Resolved: Required fields missing, skipping storage');
  return []; // Return empty array to skip Supabase insert
}

// Map to database schema (snake_case for Supabase)
// Database expects: user_email, issue_description, solution, issue_type
return [{
  json: {
    user_email: userEmail, // REQUIRED: Map camelCase to snake_case for Supabase
    issue_description: query, // REQUIRED: Map query to issue_description
    solution: response, // REQUIRED: Map response to solution
    issue_type: data.insights?.issueType || null, // Optional: Map issueType
    // Preserve other fields for reference
    userEmail: userEmail,
    query: query,
    response: response,
    insights: data.insights,
    shouldStore: true
  }
}];

// Analyze conversation for learning insights
const items = $input.all();
if (items.length === 0) return [{ json: {} }];

// Get data from Universal Formatter (which now includes context)
const formatterData = items[0].json;
const response = (formatterData.response || "").toLowerCase();
const query = (formatterData.query || "").toLowerCase();
const userEmail = formatterData.userEmail || null;

// Extract insights
const insights = {
  issueType: null,
  wasResolved: response.includes('resolved') || response.includes('fixed') || response.includes('solved'),
  kbUsed: response.includes('knowledge') || response.includes('article'),
  ticketCreated: response.includes('incident') || response.includes('ticket') || response.includes('created'),
  userSatisfaction: null // Could be extracted from follow-up or survey
};

// Detect issue type from query
if (query.match(/password|login|access|credential/i)) insights.issueType = 'authentication';
else if (query.match(/printer|print/i)) insights.issueType = 'hardware';
else if (query.match(/email|outlook|mail/i)) insights.issueType = 'email';
else if (query.match(/network|wifi|internet|connection/i)) insights.issueType = 'network';
else if (query.match(/software|application|app|program/i)) insights.issueType = 'software';

// Merge all data: context from formatter + response + insights
return [{
  json: {
    ...formatterData, // userEmail, query, sessionId, response, etc.
    insights: insights
  }
}];

// Store discovery data with timestamp for caching
const items = $input.all();
if (items.length === 0) return [{ json: { error: "No data" } }];

const data = items[0].json;

return [{
  json: {
    ...data,
    lastDiscoveryFetch: Date.now(),
    cachedAt: new Date().toISOString()
  }
}];

// Check if discovery data is cached (1 hour TTL)
const items = $input.all();
if (items.length === 0) return [{ json: { useCache: false } }];

const data = items[0].json;
const cacheKey = 'ivanti_discovery_cache';
const cacheTTL = 3600000; // 1 hour in milliseconds

// Try to get from Redis or check timestamp
// For now, we'll use a simple approach: always fetch if > 1 hour since last fetch
// In production, use Redis or database cache

// This is a placeholder - in real implementation, check Redis/database
const lastFetch = data.lastDiscoveryFetch || 0;
const now = Date.now();
const useCache = (now - lastFetch) < cacheTTL;

return [{
  json: {
    ...data,
    useCache: useCache,
    cacheAge: useCache ? Math.floor((now - lastFetch) / 1000 / 60) : null // minutes
  }
}];

// Prepare user pattern data for upsert
const items = $input.all();
if (items.length === 0) return [{ json: {} }];

const data = items[0].json;
const userEmail = data.user_email || data.userEmail;
const intent = data.route || 'unknown';

// Try to get existing pattern to increment frequency
let existingPattern = null;
try {
  const patterns = $('Load User Patterns').all();
  existingPattern = patterns.find(p => 
    p.json.user_email === userEmail && p.json.common_intent === intent
  );
} catch (e) {
  // If Load User Patterns hasn't run or failed, start with frequency 1
}

// Ensure frequency is a proper integer (not string)
const existingFreq = existingPattern ? (existingPattern.json.frequency || 1) : 1;
const newFrequency = parseInt(existingFreq, 10) + 1;

// Output in database format for Supabase node
// Ensure all types are correct: frequency as number, last_used as ISO string
return [{
  json: {
    user_email: userEmail, // For matching/select condition
    common_intent: intent, // For matching/select condition
    frequency: newFrequency, // Value to update (explicitly as number)
    last_used: new Date().toISOString() // Update timestamp
  }
}];

// Format AI response for Supabase storage
// Universal Formatter already provides all needed fields
const items = $input.all();
if (items.length === 0) return [];

const data = items[0].json;

// Extract AI response (Universal Formatter outputs 'response' field)
const aiResponse = data.response || data.message_content || data.text || data.output || '';

// Use data directly from Universal Formatter (it already has user_email, session_id, etc.)
// Universal Formatter outputs both camelCase and snake_case, prefer snake_case for Supabase
const userEmail = data.user_email || data.userEmail;
const sessionId = data.session_id || data.sessionId;
const userContext = data.userContext;
const route = data.route;

// VALIDATION: Skip if required fields are missing
if (!userEmail || !sessionId || !aiResponse) {
  console.warn('Format AI Response: Missing required fields:', {
    userEmail: !!userEmail,
    sessionId: !!sessionId,
    aiResponse: !!aiResponse,
    dataKeys: Object.keys(data)
  });
  return [];
}

// Map to database schema (snake_case for Supabase)
// conversation_history expects: user_email, session_id, message_role, message_content, ticket_id, intent
return [{
  json: {
    user_email: userEmail,
    session_id: sessionId,
    message_role: 'assistant',
    message_content: aiResponse,
    ticket_id: userContext?.ticketId || null,
    intent: route || null
  }
}];

// Format user message for Supabase storage
// Universal Formatter provides context, but we need the original query
const items = $input.all();
if (items.length === 0) return [];

const data = items[0].json;

// Use data directly from Universal Formatter (it preserves query, userEmail, sessionId)
// Universal Formatter outputs both camelCase and snake_case, prefer snake_case for Supabase
const userEmail = data.user_email || data.userEmail;
const sessionId = data.session_id || data.sessionId;
const query = data.query || data.message_content || '';
const userContext = data.userContext;
const route = data.route;

// VALIDATION: Skip if required fields are missing
if (!userEmail || !sessionId || !query) {
  console.warn('Format User Message: Missing required fields:', {
    userEmail: !!userEmail,
    sessionId: !!sessionId,
    query: !!query,
    dataKeys: Object.keys(data)
  });
  return [];
}

// Map to database schema (snake_case for Supabase)
// conversation_history expects: user_email, session_id, message_role, message_content, ticket_id, intent
return [{
  json: {
    user_email: userEmail,
    session_id: sessionId,
    message_role: 'user',
    message_content: query,
    ticket_id: userContext?.ticketId || null,
    intent: route || null
  }
}];

// FAST PATH ROUTER - Skip heavy processing for simple queries
const items = $input.all();
if (items.length === 0) return [{ json: { error: "No data" } }];

const data = items[0].json;
const forcedIntent = data.forcedIntent;
const query = (data.query || "").toLowerCase().trim();

// Fast path conditions:
// 1. forcedIntent is 'lookup' or 'my_tickets'
// 2. OR query is clearly a simple ticket lookup
const isFastPath = forcedIntent === 'lookup' || forcedIntent === 'my_tickets' ||
                   query.match(/^(show|check|list|my|what).*ticket/i) ||
                   query.match(/^status.*inc-/i) ||
                   query.match(/^where.*request/i);

return [{
  json: {
    ...data,
    useFastPath: isFastPath,
    routeIntent: forcedIntent || (isFastPath ? 'auto_fast' : null)
  }
}];
